WITH filtered AS (SELECT id, customer_id, browser, started_at, country, DATE_FORMAT(started_at, 'MMM yyyy') AS started_at_label, TRIM(device) AS clean_device FROM sessions WHERE started_at >= TIMESTAMP '2023-08-29 07:00:00' AND country IS NOT NULL) SELECT id, customer_id, browser, started_at, country, started_at_label, clean_device, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY started_at ASC, id ASC) AS event_seq, ROW_NUMBER() OVER (PARTITION BY browser ORDER BY started_at ASC, id ASC) AS seq_no, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY started_at DESC, id ASC) AS event_seq_2 FROM filtered
